        $events = [['Студенческая конференция: первые исследования', 'Конференция', 30, '10:00', 'Очно', 'Демонстрационный анонс конференции: участники представляют первые исследовательские работы и обсуждают их с наставниками. Это пример оформления, не реальное объявление КГУ.'], ['Конференция молодых исследователей: обмен опытом', 'Конференция', -30, '11:00', 'Смешанный формат', 'Демонстрационная карточка прошедшей конференции: обсуждение проектов и исследовательских методов. Событие вымышлено для показа раздела.'], ['Первая встреча: с чего начинается наука', 'Ознакомительная встреча', 6, '16:00', 'Очно', 'Пример встречи-знакомства: обсудим, как выбрать интересный вопрос и что попробовать в первый месяц.'], ['От интереса к исследовательскому вопросу', 'Практикум', 10, '17:00', 'Онлайн', 'Пример практикума: превратим широкий интерес в вопрос, на который можно ответить.'], ['Как читать научные статьи и не сдаваться', 'Семинар', 14, '15:30', 'Онлайн', 'Пример семинара: разберём структуру статьи, признаки надёжности и способы вести заметки.']];
