            ['С чего начинается хороший исследовательский вопрос?', 'Исследовательский вопрос', 'Интерес — уже хорошее начало. Разбираемся, как сделать следующий шаг.', "Начните с наблюдения\nЗапишите, что именно вас удивляет. «Социальные сети» — это область интересов, а «Как студенты проверяют новости из социальных сетей?» — возможный исследовательский вопрос.\n\nСузьте масштаб\nУкажите, кого или что вы изучаете, в каком контексте и за какой период. Проверьте, доступны ли нужные данные и достаточно ли времени.\n\nПроверьте вопрос\nМожно ли получить обоснованный ответ? Что уже известно? Какие ограничения есть у метода? Обсудите это с наставником до сбора данных.\n\nПервое действие\nСоставьте три варианта вопроса. Для каждого запишите возможный источник данных и одно ограничение."],
            ['Где искать источники и как им доверять', 'Поиск источников', 'Пять вопросов, которые стоит задать любому источнику.', "Начните с библиотечных каталогов и научных баз, доступных вашему университету. Не считайте выдачу поисковика готовым списком литературы.\n\nПроверьте автора, дату, издателя, метод и приведённые доказательства. Отделяйте обзор, первичное исследование и авторское мнение.\n\nДля каждого источника сохраните полную ссылку, дату обращения и заметку о том, зачем он нужен вашему исследованию. Сопоставляйте независимые источники.\n\nЕсли текст доступен только в пересказе, не цитируйте его как прочитанный оригинал."],
            ['Нужна ли вашему исследованию гипотеза?', 'Гипотеза', 'Гипотеза полезна не в каждом исследовательском дизайне.', "Гипотеза — проверяемое предположение о связи, различии или механизме. Она уместна, когда дизайн позволяет её проверять.\n\nВ разведочном, описательном или качественном исследовании можно начать с исследовательского вопроса. Не нужно добавлять гипотезу ради формального пункта.\n\nОбсудите с наставником, какие наблюдения подтвердят или опровергнут предположение и какие альтернативные объяснения нужно учесть."],
            ['Как выбрать метод исследования', 'Выбор метода', 'Метод следует из вопроса и доступных данных.', "Определите, какой ответ вам нужен: описание, сравнение, объяснение или интерпретация опыта.\n\nСравните источники, интервью, наблюдение, анализ данных и эксперимент. У каждого метода есть ограничения. Корреляция сама по себе не доказывает причинность.\n\nДо работы с людьми обсудите добровольное информированное согласие, конфиденциальность и применимые университетские требования. Не собирайте лишние персональные данные."],
            ['Первые шаги в работе с данными', 'Работа с данными', 'Сохранить исходные данные так же важно, как построить график.', "Сохраните исходный набор отдельно. Зафиксируйте источник, лицензию, дату получения и описание полей.\n\nВедите журнал очистки: пропуски, дубликаты, преобразования. Не удаляйте неудобные значения без обоснования.\n\nСначала посмотрите распределения и ограничения выборки. Подписывайте оси, единицы измерения и источник на графиках. Не публикуйте персональные данные."],
            ['Цитирование без случайных заимствований', 'Ссылки и заимствования', 'Как отделять свои выводы от чужих идей.', "Прямую цитату выделяйте кавычками и сопровождайте ссылкой. При пересказе своими словами источник также нужен.\n\nСохраняйте библиографические сведения при чтении, а не в последний день. Не ссылайтесь на работы, которые не проверили.\n\nСтиль ссылок и требования к оригинальности уточняйте для конкретного мероприятия или издания. Универсального обещанного процента оригинальности здесь нет."],
            ['Как рассказать об исследовании за пять минут', 'Подготовка выступления', 'Один вопрос, один главный результат и понятная структура.', "Объясните вопрос, метод, результат и ограничения. Начните с того, почему ваш вопрос интересен аудитории.\n\nНе перегружайте слайды: одна основная мысль на слайд, читаемые подписи, проверяемые источники.\n\nПроведите репетицию с таймером. Продолжительность, формат файла и оформление уточните у организаторов конкретного мероприятия. Универсальный шаблон структуры доступен в базе знаний."],
            ['От результата к рукописи статьи', 'Рукопись статьи', 'Статья — один из возможных результатов, а не обязательный финал.', "Обсудите с наставником, достаточно ли обоснованы результаты для рукописи. Проверьте соответствие темы профилю выбранного издания.\n\nТребования к объёму, структуре, ссылкам и данным берите из актуальной инструкции выбранного журнала.\n\nСогласуйте авторство и вклад, проверьте источники и разрешения. Различайте состояния: рукопись подготовлена, подана, принята и опубликована."],
        ];
        foreach ($articles as [$title,$category,$excerpt,$body]) {
            Content::firstOrCreate(['title' => $title, 'type' => 'knowledge'], compact('category', 'excerpt', 'body') + ['is_published' => true, 'is_demo' => true]);
        }
        foreach (['Нужен ли опыт?' => 'В демонстрационных задачах с отметкой «Без опыта» предусмотрен первый шаг вместе с наставником. Условия конкретной задачи указаны в её карточке.', 'Можно ли прийти без темы?' => 'Для этого предусмотрены каталог задач и подбор по интересам. Доступность ознакомительных встреч указана в описании события.', 'Нужно ли быть отличником?' => 'В демонстрационном сценарии отбор не связан с оценками. Официальные правила участия должен подтвердить организатор СНО.', 'Сколько времени занимает участие?' => 'Примерная нагрузка и сроки указаны у каждой задачи. Фактический график согласуется с наставником.'] as $title => $body) {
